// CP76 - Excel template Program guidance (real xlsx generated by buildTemplate; no DB involved)
const test = require('node:test')
const assert = require('node:assert/strict')
const zlib = require('node:zlib')
const { SPECS, buildTemplate } = require('../utils/importTemplates')

function zipEntries(buf) {
  const out = {}; let i = buf.length - 22
  while (i >= 0 && buf.readUInt32LE(i) !== 0x06054b50) i--
  let p = buf.readUInt32LE(i + 16); const n = buf.readUInt16LE(i + 10)
  for (let k = 0; k < n; k++) {
    const method = buf.readUInt16LE(p + 10), csz = buf.readUInt32LE(p + 20)
    const nl = buf.readUInt16LE(p + 28), el = buf.readUInt16LE(p + 30), cl = buf.readUInt16LE(p + 32)
    const off = buf.readUInt32LE(p + 42), name = buf.toString('utf8', p + 46, p + 46 + nl)
    const lnl = buf.readUInt16LE(off + 26), lel = buf.readUInt16LE(off + 28)
    const data = buf.subarray(off + 30 + lnl + lel, off + 30 + lnl + lel + csz)
    out[name] = method === 8 ? zlib.inflateRawSync(data).toString('utf8') : data.toString('utf8')
    p += 46 + nl + el + cl
  }
  return out
}

test('Users template Program note says custom program names are accepted', () => {
  const col = SPECS.users.columns.find(c => c.header === 'Program')
  assert.ok(col)
  assert.equal(col.field, 'program')
  assert.match(col.note, /BSIT/); assert.match(col.note, /BSOA/)
  assert.match(col.note, /custom program/i)
  assert.match(col.note, /any other program name/i)
})

test('generated Users xlsx contains the custom-program guidance; headers unchanged', () => {
  const files = zipEntries(buildTemplate('users'))
  const all = Object.values(files).join('\n')
  assert.match(all, /any other program name \(custom program/)
  const headers = SPECS.users.columns.map(c => c.header)
  assert.ok(headers.includes('Program'))
  assert.equal(new Set(headers).size, headers.length)
})

test('other templates have no Program column and no program guidance', () => {
  for (const t of ['laboratories', 'computers', 'equipment']) {
    assert.ok(!SPECS[t].columns.some(c => /program/i.test(c.header)))
    assert.doesNotMatch(Object.values(zipEntries(buildTemplate(t))).join('\n'), /custom program/i)
  }
})
